window.POETRY_REGISTER("v5-extra-10-13-0-0ae55c247281.js",{"poems":[[52066,2],[52209,2],[55193,2],[55375,2],[57946,2],[155919,7],[267739,7],[285959,7],[287948,7],[311024,7],[391217,13],[447505,8],[488531,8],[551956,8],[556446,8],[556452,8],[589734,8],[650074,5],[650377,5],[735220,5],[744370,21]],"pairs":[["正是吐蕃极盛河陇沦陷","安西北庭与中原音讯断绝之时",0],["今从知不足斋本录出之","以上九首除他人骑大马一首外",1],["其传播人口者才一二首","益柔于先子遗篇中得三十九首",2],["故对此诗之较合理解释","当是送者乃牧内兄之为郡守者",3],["第十首即署为司户萨照","盖其始赵志作第八首呈徐长史",4],["而其高明深厚所不能知","惟闻孔子之殁一百年而生孟子",5],["雄倡雌和迭舞而交鸣兮","深林自适复有雪白数点之猿猴",6],["不须怀古兮感慨而怆凄","作诗勉同志兮欲倩仙掌摩丹崖",7],["惟澹而无欲兮斯能无求","宜此心之冰坚兮凛北风之正遒",8],["不如我独鹤兮褵褷其羽","顾月池之在地兮各以影而自侣",9],["不如我独鹤兮缡褷其羽","顾月池之在地兮各以影而自侣",10],["猗丰年之兆兮此其有征","昭圣皇之神德兮溥恩泽于遐荒",11],["胡彼苍弗仁兮造化与雠","既坎壈于云途兮竟天阏于春秋",12],["爰以轻清为天重浊为地","惟有磊磊落落之石质重而韵清",13],["各有天之一体而为二支","孰使吾与尔流不得劈形不得分",14],["君不见青城山中之黄冠","非即昔日挈人头挟生虏之虎痴",15],["闹花灯高烧兮弦管噭噪","嗟耳顺之华年兮亦人生之难到",16],["这才是命里不该枉费劳","可恨那论成败的肉眼说现成话",17],["说不尽大宋无寸干净土","你看那一个汉寝唐陵不是栖鸦",17],["辜负了红粉朱楼春色阑","到头来依旧是风尘肮脏违心愿",18],["辜负了红粉朱楼春色阑","到头来依旧是风尘肮脏违心愿",19],["秋可哀兮哀南亩之菜荒","既采萧于大陆兮又刈兰乎崇冈",20]]});
